(* [comment removed for export] *)
Lemma rw_cells_ro_cell : forall segs m A cs k c,
  rw_cells segs m A cs -> cell_at cs k = Some c ->
  ro_cells segs m (A + Z.of_nat k) [c].
Proof.
  intros segs m A cs k c [[WFS BA] _] CA.
  destruct (cell_at_split cs k c c CA) as (pre & post & -> & SZ & _).
  apply cells_wf_app in WFS. destruct WFS as [W1 [W2 W3]].
  rewrite cells_bytes_app in BA. apply bytes_at_app in BA. destruct BA as [_ BA].
  cbn [cells_bytes] in BA. apply bytes_at_app in BA. destruct BA as [BA _].
  rewrite (cells_bytes_length pre W1), SZ in BA.
  split; [cbn; split; [exact W2| exact I]|].
  cbn [cells_bytes]. rewrite app_nil_r. exact BA.
Qed.

(* [comment removed for export] *)
Lemma ro_cells_ro_cell : forall segs m A cs k c,
  ro_cells segs m A cs -> cell_at cs k = Some c ->
  ro_cells segs m (A + Z.of_nat k) [c].
Proof.
  intros segs m A cs k c [WFS BA] CA.
  destruct (cell_at_split cs k c c CA) as (pre & post & -> & SZ & _).
  apply cells_wf_app in WFS. destruct WFS as [W1 [W2 W3]].
  rewrite cells_bytes_app in BA. apply bytes_at_app in BA. destruct BA as [_ BA].
  cbn [cells_bytes] in BA. apply bytes_at_app in BA. destruct BA as [BA _].
  rewrite (cells_bytes_length pre W1), SZ in BA.
  split; [cbn; split; [exact W2| exact I]|].
  cbn [cells_bytes]. rewrite app_nil_r. exact BA.
Qed.

(* [comment removed for export] *)
Lemma ones_k : forall k, 0 <= k -> 2^k - 1 = Z.ones k.
Proof. intros k Hk. unfold Z.ones. rewrite Z.shiftl_1_l. lia. Qed.

Lemma land_low_high_disj : forall k, 0 <= k <= 64 -> Z.land (2^64 - 2^k) (2^k - 1) = 0.
Proof.
  intros k Hk. rewrite (ones_k k) by lia. rewrite Z.land_ones by lia.
  replace (2^64 - 2^k) with ((2^(64-k) - 1) * 2^k) by (rewrite Z.mul_sub_distr_r, <- Z.pow_add_r by lia; f_equal; [f_equal; lia| lia]).
  apply Z.mod_mul.  lia.
Qed.

Lemma land_split_mask : forall y k, 0 <= k <= 64 -> Z.land y (2^64 - 2^k) = y mod 2^64 - y mod 2^k.
Proof.
  intros y k Hk.
  pose proof (land_low_high_disj k Hk) as D.
  assert (E : 2^64 - 1 = Z.lor (2^64 - 2^k) (2^k - 1)).
  { rewrite lor_disjoint_add by exact D. lia. }
  assert (M64 : Z.land y (2^64 - 1) = y mod 2^64) by (rewrite (ones_k 64) by lia; apply Z.land_ones; lia).
  assert (Mk : Z.land y (2^k - 1) = y mod 2^k) by (rewrite (ones_k k) by lia; apply Z.land_ones; lia).
  rewrite E in M64. rewrite Z.land_lor_distr_r in M64. rewrite lor_disjoint_add in M64.
  - rewrite Mk in M64. lia.
  - rewrite Z.land_assoc. rewrite <- (Z.land_assoc y (2^64 - 2^k) y). rewrite (Z.land_comm (2^64 - 2^k) y).
    rewrite Z.land_assoc, Z.land_diag, <- Z.land_assoc, D. apply Z.land_0_r.
Qed.

Lemma land_m4 : forall x, 0 <= x < 2^64 -> Z.land x 18446744073709551612 = x - x mod 4.
Proof. intros x Hx. change 18446744073709551612 with (2^64 - 2^2). rewrite land_split_mask by lia. rewrite Z.mod_small by lia. reflexivity. Qed.

Lemma land_m8 : forall x, 0 <= x < 2^64 -> Z.land x 18446744073709551608 = x - x mod 8.
Proof. intros x Hx. change 18446744073709551608 with (2^64 - 2^3). rewrite land_split_mask by lia. rewrite Z.mod_small by lia. reflexivity. Qed.

(* [comment removed for export] *)
Lemma u64_mod : forall e, bv_unsigned (Z_to_bv 64 e) = e mod 2^64.
Proof. intros e. rewrite Z_to_bv_unsigned. reflexivity. Qed.
Lemma Z_to_bv_mod64 : forall e, Z_to_bv 64 (e mod 2^64) = Z_to_bv 64 e.
Proof. intros e. rewrite <- land_W64. apply Z_to_bv_land64. Qed.

(* [comment removed for export] *)
Lemma rdn_bytes_at : forall n bs m (a : Z),
  Lib.PropExec.rdn usegs m (Z_to_bv 64 a) n = Some bs -> 0 <= a -> a + Z.of_nat n <= 2^64 ->
  bytes_at usegs m a bs.
Proof.
  induction n as [|n IH]; intros bs m a H Ha Hn.
  - cbn in H. injection H as <-. split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia.
  - rewrite rdn_unfold in H. fold (wa a) in H.
    destruct (mrd usegs m (wa a)) as [b|] eqn:MB; [|discriminate].
    rewrite wa_succ in H.
    destruct (Lib.PropExec.rdn usegs m (wa (a + 1)) n) as [r|] eqn:RR; [|discriminate].
    injection H as <-.
    destruct (Z.eq_dec (a + 1) (2^64)) as [E|NE].
    + (* [comment removed for export] *)
      destruct n; [|lia]. cbn in RR. injection RR as <-.
      split; [lia|]. split; [cbn; lia|]. intros [|i] Hi; cbn in Hi; [|lia]. cbn. rewrite Z.add_0_r. exact MB.
    + assert (Ha' : 0 <= a + 1) by lia. assert (Hn' : a + 1 + Z.of_nat n <= 2^64) by lia.
      pose proof (IH r m (a + 1) RR Ha' Hn') as (_ & HB & IH3).
      split; [lia|]. split; [cbn [length]; lia|].
      intros [|i] Hi; cbn [nth_error]; [rewrite Z.add_0_r; exact MB|].
      rewrite <- (IH3 i) by (cbn in Hi; lia). f_equal. f_equal. lia.
Qed.

Lemma bytes_at_rdn8 : forall m (a : Z) bs,
  bytes_at usegs m a bs -> length bs = 8%nat -> Lib.PropExec.rdn usegs m (Z_to_bv 64 a) 8 = Some bs.
Proof.
  intros m a bs H L. pose proof (bytes_at_rdn usegs m a bs 0 8 H ltac:(lia)) as R.
  cbn [Z.of_nat skipn] in R. rewrite Z.add_0_r in R. rewrite <- L, firstn_all in R. rewrite L in R. exact R.
Qed.

Definition CanaryCells (m : mem) (can : Z) : Prop :=
  ro_cells usegs m G_GOT_STACK_CHK [C8 (wz G_STACK_CHK_GUARD)] /\ ro_cells usegs m G_STACK_CHK_GUARD [C8 (wz can)].

Lemma CanaryReads_cells : forall m, CanaryReads m -> exists can, 0 <= can < 2^64 /\ CanaryCells m can.
Proof.
  intros m [G [can C]]. exists (can mod 2^64). split; [apply Z.mod_pos_bound; lia|].
  unfold CanaryCells, G_GOT_STACK_CHK, G_STACK_CHK_GUARD, wz in *. split.
  - split; [cbn; split; [reflexivity| exact I]|]. cbn [cells_bytes cbytes app].
    eapply rdn_bytes_at; [exact G| lia| cbn; lia].
  - split; [cbn; split; [reflexivity| exact I]|]. cbn [cells_bytes cbytes app].
    rewrite Z_to_bv_mod64. eapply rdn_bytes_at; [exact C| lia| cbn; lia].
Qed.

Lemma CanaryCells_reads : forall m can, CanaryCells m can -> CanaryReads m.
Proof.
  intros m can [[_ A] [_ B]]. cbn [cells_bytes cbytes app] in A, B. rewrite app_nil_r in A, B.
  unfold CanaryReads. split.
  - exact (bytes_at_rdn8 _ _ _ A eq_refl).
  - exists can. exact (bytes_at_rdn8 _ _ _ B eq_refl).
Qed.

Lemma CanaryCells_transport : forall W m m' can,
  CanaryCells m can -> munch W m m' ->
  disjoint_from W G_GOT_STACK_CHK 8 -> disjoint_from W G_STACK_CHK_GUARD 8 -> CanaryCells m' can.
Proof.
  intros W m m' can [A B] MU D1 D2. split.
  - eapply ro_cells_transport; [exact A| exact MU| exact D1].
  - eapply ro_cells_transport; [exact B| exact MU| exact D2].
Qed.

Lemma CanaryReads_transport : forall W m m',
  CanaryReads m -> munch W m m' ->
  disjoint_from W G_GOT_STACK_CHK 8 -> disjoint_from W G_STACK_CHK_GUARD 8 -> CanaryReads m'.
Proof.
  intros W m m' CR MU D1 D2. destruct (CanaryReads_cells m CR) as (can & _ & CC).
  eapply CanaryCells_reads. eapply CanaryCells_transport; eauto.
Qed.

(* [comment removed for export] *)
Definition is_nulb (b : byte) : bool := bv_unsigned b =? 0.
Definition has_nul (l : list byte) : bool := existsb is_nulb l.

(* [comment removed for export] *)
Fixpoint strcmp_val (l r : list byte) : Z :=
  match l, r with
  | c :: l', d :: r' =>
      if is_nulb c || negb (bv_unsigned c =? bv_unsigned d) then bv_unsigned c - bv_unsigned d
      else strcmp_val l' r'
  | _, _ => 0
  end.

Lemma skipn_nth_error_cons : forall {X} (l : list X) i c,
  nth_error l i = Some c -> skipn i l = c :: skipn (S i) l.
Proof.
  induction l as [|x l IH]; intros [|i] c H; cbn in *; try discriminate.
  - injection H as ->. reflexivity.
  - apply IH. exact H.
Qed.

Lemma has_nul_skipn_some : forall l i, has_nul (skipn i l) = true -> exists c, nth_error l i = Some c.
Proof.
  intros l i H. destruct (nth_error l i) as [c|] eqn:E; [exists c; reflexivity|].
  apply nth_error_None in E. rewrite skipn_all2 in H by lia. discriminate H.
Qed.

Lemma byte_range : forall b : byte, 0 <= bv_unsigned b < 256.
Proof. intros b. pose proof (bv_unsigned_in_range 8 b) as H. unfold bv_modulus in H. cbn in H. lia. Qed.

(* [comment removed for export] *)
Definition lit_bytes (a : Z) (n : nat) : list byte :=
  match image_bytes usegs a n with Some bs => bs | None => [] end.

