(* [comment removed for export] *)
(* [comment removed for export] *)

Definition align_up (al p : Z) : Z := Z.land ((p + al - 1) mod 2^64) ((- al) mod 2^64).
Definition align_d (al p : Z) : Z := (align_up al p - p) mod 2^64.
Definition std_align_res (al sz p spc : Z) : option (Z * Z) :=
  if spc <? sz then None
  else if spc - sz <? align_d al p then None
  else Some (align_up al p, spc - align_d al p).

Lemma align_up_range : forall al p, 0 <= align_up al p < 2^64.
Proof.
  intros al p. unfold align_up. apply Z_land_range; [apply Z.mod_pos_bound; lia| apply Z.mod_pos_bound; lia].
Qed.

Lemma align_up_aligned8 : forall p, 0 <= p < 2^64 -> p mod 8 = 0 -> align_up 8 p = p.
Proof.
  intros p HP AL. unfold align_up.
  replace ((p + 8 - 1) mod 2^64) with (p + 7) by (rewrite Z.mod_small; [lia| Z.div_mod_to_equations; lia]).
  change ((-8) mod 2^64) with 18446744073709551608. rewrite land_m8 by (Z.div_mod_to_equations; lia).
  Z.div_mod_to_equations; lia.
Qed.

Lemma std_align_res_aligned8 : forall sz p spc,
