Definition std_align_W (PA SA : Z) : list (Z * Z) := [(PA, PA + 8); (SA, SA + 8)]%Z.

Definition std_align_post (ra sp gp tp s0 s1 a2 a3 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (al sz PA SA p spc : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a4 a5 a6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (std_align_W PA SA) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ match std_align_res al sz p spc with
       | None => a0 = wz 0 /\ rw_cells usegs m' PA [C8 (wz p)] /\ rw_cells usegs m' SA [C8 (wz spc)]
       | Some (a, spc') => a0 = wz a /\ rw_cells usegs m' PA [C8 (wz a)] /\ rw_cells usegs m' SA [C8 (wz spc')]
       end.

Definition std_align_stmt : Prop :=
  forall (al sz PA SA p spc : Z) ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells usegs m PA [C8 (wz p)] -> rw_cells usegs m SA [C8 (wz spc)] ->
  (PA + 8 <= SA \/ SA + 8 <= PA) ->
  0 <= al < 2^64 -> 0 <= sz < 2^64 -> 0 <= p < 2^64 -> 0 <= spc < 2^64 ->
  mem_inv usegs m ->
  evt usegs (std_align_post ra sp gp tp s0 s1 (wz PA) (wz SA) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc al sz PA SA p spc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz al) (wz sz) (wz PA) (wz SA) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_STD_ALIGN) fc None m (seg_rom usegs)).

(* [comment removed for export] *)
Lemma std_align_aligned_eq : forall al p, 0 <= al < 2^64 ->
  Z_to_bv 64 (Z.land (bv_unsigned (Z_to_bv 64 (p + al + -1))) (bv_unsigned (Z_to_bv 64 (0 + - bv_unsigned (Z_to_bv 64 al)))))
  = wz (align_up al p).
Proof.
  intros al p AL. unfold wz, align_up. f_equal. rewrite !u64_mod. rewrite (Z.mod_small al) by lia.
  f_equal; f_equal; lia.
Qed.

