Definition P_STRCMP_LOOP : Z := 0x79be0.

Definition strcmp_post (ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (v : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz v) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m (seg_rom usegs)
    /\ munch [] m m /\ wmono usegs m m /\ mem_inv usegs m.

(* [comment removed for export] *)
Local Ltac strcmp_end c d i lb rb :=
  rewrite (unsigned_lit (bv_unsigned d)) by lia;
  replace (Z_to_bv 64 (bv_unsigned c + - bv_unsigned d)) with (wz (strcmp_val (c :: skipn (S i) lb) (d :: skipn (S i) rb)));
  [ finish
  | unfold wz; cbn [strcmp_val]; unfold is_nulb;
    repeat match goal with
           | K : bv_unsigned _ = _ |- _ => rewrite (proj2 (Z.eqb_eq _ _) K); clear K
           | K : bv_unsigned _ <> _ |- _ => rewrite (proj2 (Z.eqb_neq _ _) K); clear K
           end;
    cbn [orb negb]; try (f_equal; lia) ].

Lemma strcmp_loop : forall (k : nat) (L R : Z) (lb rb : list byte) (i : nat)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (length lb - i <= k)%nat ->
  bytes_at usegs m L lb -> bytes_at usegs m R rb ->
  has_nul (skipn i lb) = true -> has_nul (skipn i rb) = true ->
  mem_inv usegs m ->
  evt usegs (strcmp_post ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc
               (strcmp_val (skipn i lb) (skipn i rb)) m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (L + Z.of_nat i)) (wz (R + Z.of_nat i)) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_STRCMP_LOOP) fc None m (seg_rom usegs)).
